      "observed": "C1 value is 0.1uF/16V.",
      "expected": "C1 should be 1uF/25V per the specification's EPD driver component table.",
      "evidence": [
        {
          "source": "spec",
          "quote": "C1/C5/C7/C8/C9/C10 = 1 µF/25 V"
